urlset:
{%- set site_url = "https://swimfrancisco.com" %}
{%- set locale_data = load_data(path="data/locales.toml") %}
{%- for entry in entries %}
  {%- set_global canonical_url = entry.permalink %}
  {%- for locale in locale_data.locales %}
    {%- if not locale.is_default %}
      {%- set_global canonical_url = canonical_url | replace(from=site_url ~ "/" ~ locale.code ~ "/", to=site_url ~ "/") %}
    {%- endif %}
  {%- endfor %}

    {{ entry.permalink | safe }}
    {%- for locale in locale_data.locales %}
      {%- if locale.is_default %}
        {%- set locale_url = canonical_url %}
      {%- else %}
        {%- set locale_url = canonical_url | replace(from=site_url ~ "/", to=site_url ~ "/" ~ locale.code ~ "/") %}
      {%- endif %}

    {%- endfor %}

    {%- if entry.updated %}
    {{ entry.updated }}
    {%- endif %}

{%- endfor %}
